import org.junit.jupiter.api.io.TempDir;
import org.junitpioneer.jupiter.SetSystemProperty;

/** Exercises a selected physical statement access from packed search through an actual cursor. */
class LmdbUnifiedPhysicalPlanningTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:unified-physical:p");
	private static final IRI OTHER_PREDICATE = VF.createIRI("urn:unified-physical:other");
	private static final String QUERY = "SELECT ?s ?o WHERE { ?s <" + PREDICATE + "> ?o }";

	@Test
	@SetSystemProperty(key = "rdf4j.optimizer.lmdb.cascades.mode", value = "exact")
	void selectedStatementAccessMatchesTheExecutedSource(@TempDir Path root) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,pocs")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L)
				.setFrontierHeapBudgetBytes(512L * 1024L * 1024L);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(root.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			Map<List<Value>, Integer> expected = new HashMap<>();
			try (RepositoryConnection writer = repository.getConnection()) {
				writer.begin();
				for (int i = 0; i < 32; i++) {
					IRI subject = VF.createIRI("urn:unified-physical:s:" + i);
					Value object = VF.createLiteral(i);
					writer.add(subject, PREDICATE, object);
					expected.merge(List.of(subject, object), 1, Integer::sum);
					writer.add(subject, OTHER_PREDICATE, VF.createLiteral("unrelated-" + i));
				}
				writer.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());

			try (RepositoryConnection connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(QUERY).explain(Explanation.Level.Telemetry);
				assertEquals(expected, resultBag(connection), "the complete RDF result bag");
				TupleExpr executed = (TupleExpr) explanation.tupleExpr();
				List<StatementPattern> patterns = patterns(executed);
				assertEquals(1, patterns.size(), explanation.toString());
				StatementPattern pattern = patterns.getFirst();
				String selected = pattern.getStringMetricPlanned("optimizer.selectedPhysicalRecipe");
				String actual = pattern.getStringMetricActual("optimizer.executedPhysicalRecipe");
				String runtimePlan = runtimePlan(executed);

				assertAll(
						() -> assertTrue(pattern.getLongMetricPlanned("optimizer.physicalCandidateCount") >= 2,
								"at least two configured executable index candidates must compete"),
						() -> assertTrue(pattern.getLongMetricPlanned("optimizer.physicalQuoteCount") >= 2,
								"the competing indexes must receive physical quotes"),
						() -> assertNotNull(selected, "packed search must identify its selected executable recipe"),
						() -> assertNotNull(actual, "the bound cursor must report its actual physical recipe"),
						() -> assertFalse(selected == null || selected.isBlank(), "selected recipe identity"),
						() -> assertEquals(selected, actual, "a valid selected index must be the index executed"),
						() -> assertNotNull(runtimePlan, "the actual native cursor plan must be reported"),
						() -> assertTrue(runtimePlan != null
								&& Pattern.compile("source: LMDB\\s+outcome: SELECTED").matcher(runtimePlan).find(),
								"the telemetry must contain an actual LMDB access selection: " + runtimePlan),
						() -> assertTrue(runtimePlan != null && runtimePlan.contains("rowsMatchedActual: 32"),
								"the selected access must report the rows that produce the result bag: " + runtimePlan),
						() -> assertTrue(actual != null && runtimePlan != null && runtimePlan.contains(actual),
								"the actual receipt must also be attached to the observed cursor event: "
										+ runtimePlan));
			}
		} finally {
			repository.shutDown();
		}
	}

	private static Map<List<Value>, Integer> resultBag(RepositoryConnection connection) {
		Map<List<Value>, Integer> result = new HashMap<>();
		try (var rows = connection.prepareTupleQuery(QUERY).evaluate()) {
			while (rows.hasNext()) {
				var row = rows.next();
				result.merge(List.of(row.getValue("s"), row.getValue("o")), 1, Integer::sum);
			}
		}
		return result;
	}

	private static List<StatementPattern> patterns(TupleExpr expression) {
		List<StatementPattern> result = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				result.add(pattern);
			}
		});
		return result;
	}

	private static String runtimePlan(TupleExpr expression) {
		String[] plan = { null };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (plan[0] == null) {
					plan[0] = node.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
				}
				super.meetNode(node);
			}
		});
		return plan[0];
	}
}
